import React, { useState } from "react";
import useLocalStorage from "./hooks/useLocalStorage";
import AddTask from "./components/AddTask";
import TaskList from "./components/TaskList";
import FilterButtons from "./components/FilterButton";
import { createTask } from "./utils";

export default function App() {
    const [tasks, setTasks] = useLocalStorage("mini-task-manager.tasks", []);
    const [filter, setFilter] = useState("all");

    const addTask = (title) => {
        const newTask = createTask(title);
        setTasks([newTask, ...tasks]);
    };

    const toggleTask = (id) => {
        setTasks(tasks.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t)));
    };

    const deleteTask = (id) => setTasks(tasks.filter((t) => t.id !== id));

    const editTask = (id, title) => setTasks(tasks.map((t) => (t.id === id ? { ...t, title } : t)));

    const total = tasks.length;
    const completed = tasks.filter((t) => t.completed).length;
    const incomplete = total - completed;

    return (
        <div className="app-shell">
            <div className="app-card">
                <header style={{ marginBottom: '1rem' }}>
                    <h1 className="app-title">Task Manager</h1>
                    <p className="text-muted" style={{ marginBottom: '1rem' }}>Organize your tasks efficiently</p>

                    <div style={{ display: 'flex', gap: '1rem', marginTop: '0.75rem' }}>
                        <div style={{ flex: 1, background: 'rgba(99,102,241,0.06)', padding: '1rem', borderRadius: '0.5rem', textAlign: 'center' }}>
                            <div style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--indigo-600)' }}>{total}</div>
                            <div className="text-muted">Total Tasks</div>
                        </div>
                        <div style={{ flex: 1, background: 'rgba(16,185,129,0.06)', padding: '1rem', borderRadius: '0.5rem', textAlign: 'center' }}>
                            <div style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--green-600)' }}>{completed}</div>
                            <div className="text-muted">Completed</div>
                        </div>
                        <div style={{ flex: 1, background: 'rgba(249,115,22,0.04)', padding: '1rem', borderRadius: '0.5rem', textAlign: 'center' }}>
                            <div style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--yellow-600)' }}>{incomplete}</div>
                            <div className="text-muted">Incomplete</div>
                        </div>
                    </div>
                </header>

                <section style={{ marginBottom: '1rem' }}>
                    <h2 style={{ margin: '0 0 0.5rem 0', fontWeight: 600 }}>Add New Task</h2>
                    <AddTask onAdd={addTask} />
                </section>

                <section style={{ marginBottom: '1rem' }}>
                    <h3 style={{ margin: '0 0 0.5rem 0', fontWeight: 600 }}>Filter Tasks</h3>
                    <FilterButtons filter={filter} setFilter={setFilter} counts={{ total, completed, incomplete }} />
                </section>

                <section>
                    <h3 style={{ margin: '0 0 0.75rem 0', fontWeight: 600 }}>All Tasks</h3>
                    <TaskList tasks={tasks} filter={filter} onToggle={toggleTask} onDelete={deleteTask} onEdit={editTask} />
                </section>
            </div>
        </div>
    );
}
